def style_map(styler, func, subset=None):
    """Version-safe Styler.map / Styler.applymap."""
    if hasattr(styler, "map"):
        return styler.map(func, subset=subset)
    return styler.applymap(func, subset=subset)

def embed_html(html, height=600):
    """Newer Streamlit uses st.iframe; older versions fall back to components.html."""
    if hasattr(st, "iframe"):
        return st.iframe(html, height=height)
    return components.html(html, height=height)

