def logo_img(height=40):
    if not LOGO_URI:
        return (f'<div style="font-family:Inter,Arial,sans-serif;font-weight:800;letter-spacing:{max(2, height // 6)}px;'
                f'font-size:{int(height * 0.62)}px;color:#fff;line-height:1;border-bottom:{max(2, height // 12)}px solid #FF7A45;'
                f'display:inline-block;padding-bottom:3px;">MOROPORO</div>')
    return f'<img src="{LOGO_URI}" alt="MOROPORO" style="height:{height}px;width:auto;display:block;">'

def login_logo():
    return f'<div class="mp-login-logo">{logo_img(54)}</div>'

def sidebar_brand(user="ADMIN"):
    return (f'<div class="mp-side-brand">{logo_img(30)}'
            f'<div class="mp-side-user">Signed in as <b>{user}</b></div>'
            f'<div class="mp-side-dev">Developed by Sid Ivan R. Piquero</div></div>')

def page_header(date_text=""):
    chip = f'<span class="mp-chip"><b>{date_text}</b></span>' if date_text else ""
    return (f'<div class="mp-header"><div>{logo_img(48)}'
            f'<div class="mp-tag">Heat index intelligence for Philippine schools and communities</div></div>'
            f'<div class="mp-chips">{chip}<span class="mp-chip">Developed by <b>Sid Ivan R. Piquero</b></span></div></div>')

def stat_strip(items):
    """One clean card with evenly divided stats: items = [(label, value), ...]"""
    cells = "".join(f'<div class="stat"><div class="stat-l">{l}</div><div class="stat-v">{v}</div></div>' for l, v in items)
    return f'<div class="stat-strip" style="--n:{len(items)}">{cells}</div>'

