# ------------------------------------------------------------------ short-range data
@st.cache_data(ttl=1800, show_spinner=False)
def _fetch_openmeteo(lat, lon):
    """Raises on failure so Streamlit does not cache the failure."""
    r = requests.get(OM_URL, timeout=12, params={
        "latitude": round(float(lat), 4), "longitude": round(float(lon), 4),
        "hourly": "temperature_2m,relative_humidity_2m",
        "daily": "precipitation_probability_max",
        "timezone": "Asia/Manila", "forecast_days": OM_MAX_DAYS,
    })
    r.raise_for_status()
    js = r.json()
    hourly = pd.DataFrame({
        "time": pd.to_datetime(js["hourly"]["time"]),
        "t": js["hourly"]["temperature_2m"],
        "rh": js["hourly"]["relative_humidity_2m"],
    }).dropna()
    daily = pd.DataFrame({
        "date": pd.to_datetime(js["daily"]["time"]).date,
        "rain": js["daily"].get("precipitation_probability_max", [None] * len(js["daily"]["time"])),
    })
    return hourly, daily


def _model_daily_peaks(hourly, daily, hi_fn):
    h = hourly.copy()
    t = h["t"].to_numpy(float)
    h["hi"] = np.maximum(hi_fn(t, h["rh"].to_numpy(float)), t)
    h["date"] = h["time"].dt.date
    peak = h.loc[h.groupby("date")["hi"].idxmax()].set_index("date")
    out = pd.DataFrame({"HI": peak["hi"], "Temp": peak["t"], "RH": peak["rh"]})
    return out.join(daily.set_index("date")["rain"].rename("Rain"))


def _climatology(df_daily, station, d, trend_rate, offset):
    s = df_daily[["Date", station]].dropna()
    doy = s["Date"].dt.dayofyear.to_numpy()
    diff = np.abs(doy - pd.Timestamp(d).dayofyear)
    diff = np.minimum(diff, 365 - diff)
    w = s.loc[diff <= 3, station]
    if w.empty:
        w = s[station]
    mid_year = (s["Date"].dt.year.min() + s["Date"].dt.year.max()) / 2.0
    mean = float(w.mean()) + trend_rate * (d.year - mid_year) + offset
    sd = float(w.std()) if len(w) > 1 else 1.0
    return mean, (0.0 if np.isnan(sd) else sd)


def build_forecast(lat, lon, n_days, start_date, df_daily, station, trend_rate, offset, hi_fn, classify_fn):
    """Daily peaks. Returns (DataFrame, warning_text_or_None)."""
    warn, model = None, None
    try:
        hourly, daily = _fetch_openmeteo(lat, lon)
        model = _model_daily_peaks(hourly, daily, hi_fn)
    except Exception:
        warn = ("The forecast service could not be reached, so every day below is a climatological outlook "
                "(historical average + trend), not a weather forecast.")
    today_ref = (datetime.now(timezone.utc) + timedelta(hours=8)).date()
    rows = []
    for i in range(n_days):
        d = start_date + timedelta(days=i)
        lead = (d - today_ref).days
        if model is not None and d in model.index and 0 <= lead < OM_MAX_DAYS:
            r = model.loc[d]
            hi_model, spread = float(r["HI"]), 0.0
            ext = external_peak_hi_p(lat, lon, d, station)
            if ext:
                hi_model, spread = 0.5 * hi_model + 0.5 * ext["mean"], ext["spread"]
            mean, sd = _climatology(df_daily, station, d, trend_rate, offset)
            w = ext_weight(lead, spread)
            hi = w * hi_model + (1 - w) * mean
            half = float(np.sqrt((w * max(spread, 0.5)) ** 2 + ((1 - w) * (0.0 if np.isnan(sd) else sd)) ** 2))
            lo_b, hi_b = hi - half, hi + half
            src, temp, rh = "Forecast", float(r["Temp"]), float(r["RH"])
            rain = None if pd.isna(r["Rain"]) else float(r["Rain"])
        else:
            mean, sd = _climatology(df_daily, station, d, trend_rate, offset)
            hi, lo_b, hi_b = mean, mean - sd, mean + sd
            src, temp, rh, rain = "Outlook", np.nan, np.nan, None
        z = classify_fn(float(hi))
        rows.append({"Date": d, "Label": d.strftime("%d %b"), "Sub": d.strftime("%a"), "HI": round(hi, 1),
                     "Low": None if lo_b is None else round(lo_b, 1),
                     "High": None if hi_b is None else round(hi_b, 1),
                     "Temp": temp, "RH": rh, "Rain": rain, "Source": src,
                     "Level": z["label"], "Color": z["color"]})
    return pd.DataFrame(rows), warn


# ------------------------------------------------------------------ long-range data
def build_longterm(hist_years, hist_vals, start_year, end_year, offset, classify_fn):
    """Linear trend of annual peak HI + location offset, 95 % prediction interval. Returns (df, info) or (None, msg)."""
    x = np.asarray(hist_years, float)
    y = np.asarray(hist_vals, float)
    ok = ~np.isnan(y)
    x, y = x[ok], y[ok]
    n = len(x)
    if n < 4 or np.ptp(x) == 0:
        return None, "Not enough historical years to fit a trend."
    slope, intercept = np.polyfit(x, y, 1)
    res = y - (intercept + slope * x)
    s = float(np.sqrt(np.sum(res ** 2) / (n - 2)))
    xbar, sxx = float(x.mean()), float(np.sum((x - x.mean()) ** 2))
    tcrit = float(stats.t.ppf(0.975, n - 2))
    years = np.arange(int(start_year), int(end_year) + 1)
    mean = np.clip(intercept + slope * years, 0, 65.0) + offset
    half = tcrit * s * np.sqrt(1 + 1 / n + (years - xbar) ** 2 / sxx)
    rows = []
    for yr, m, h in zip(years, mean, half):
        z = classify_fn(float(m))
        rows.append({"Date": None, "Year": int(yr), "Label": str(int(yr)), "Sub": "", "HI": round(float(m), 1),
                     "Low": round(float(m - h), 1), "High": round(float(m + h), 1),
                     "Temp": np.nan, "RH": np.nan, "Rain": None, "Source": "Projection",
                     "Level": z["label"], "Color": z["color"]})
    return pd.DataFrame(rows), {"slope": float(slope), "n_hist": n, "resid_sd": s}


# ------------------------------------------------------------------ receipt graphics (inline SVG)
def _svg_bars(df, note):
    W, H, L, R, T, B = 360, 178, 30, 8, 14, 34
    pw, ph = W - L - R, H - T - B
    lo = min(24.0, float(np.floor(df["Low"].fillna(df["HI"]).min())) - 1)
    hi = max(44.0, float(np.ceil(df["High"].fillna(df["HI"]).max())) + 1)
    Y = lambda v: T + ph * (1 - (v - lo) / (hi - lo))
    n = len(df)
    slot = pw / n
    bw = slot * 0.68
    p = [f'<svg viewBox="0 0 {W} {H}" width="100%" xmlns="http://www.w3.org/2000/svg" font-family="Courier New,monospace">']
    for v in range(int(np.ceil(lo / 5) * 5), int(hi) + 1, 5):
        p.append(f'<line x1="{L}" y1="{Y(v):.1f}" x2="{W-R}" y2="{Y(v):.1f}" stroke="#e6e6e6" stroke-width=".5"/>'
                 f'<text x="{L-4}" y="{Y(v)+2.5:.1f}" font-size="7" text-anchor="end" fill="#555">{v}</text>')
    for v, lab in ((27, "HINAY"), (33, "HINGA"), (42, "HINTO")):
        if lo < v < hi:
            p.append(f'<line x1="{L}" y1="{Y(v):.1f}" x2="{W-R}" y2="{Y(v):.1f}" stroke="#000" stroke-width=".7" stroke-dasharray="3,2"/>'
                     f'<text x="{W-R}" y="{Y(v)-2:.1f}" font-size="6.5" text-anchor="end" fill="#000">{lab} {v}&#176;</text>')
    step = max(1, int(np.ceil(n / 7)))
    for i, (_, r) in enumerate(df.iterrows()):
        x = L + i * slot + (slot - bw) / 2
        y = Y(r["HI"])
        faded = r["Source"] == "Outlook"
        p.append(f'<rect x="{x:.1f}" y="{y:.1f}" width="{bw:.1f}" height="{max(Y(lo)-y,0.5):.1f}" fill="{r["Color"]}" '
                 f'fill-opacity="{0.45 if faded else 1}" stroke="#000" stroke-width=".5"/>')
        if not pd.isna(r["Low"]) and not pd.isna(r["High"]):
            cx = x + bw / 2
            p.append(f'<line x1="{cx:.1f}" y1="{Y(r["High"]):.1f}" x2="{cx:.1f}" y2="{Y(r["Low"]):.1f}" stroke="#000" stroke-width=".8"/>'
                     f'<line x1="{cx-2:.1f}" y1="{Y(r["High"]):.1f}" x2="{cx+2:.1f}" y2="{Y(r["High"]):.1f}" stroke="#000" stroke-width=".8"/>'
                     f'<line x1="{cx-2:.1f}" y1="{Y(r["Low"]):.1f}" x2="{cx+2:.1f}" y2="{Y(r["Low"]):.1f}" stroke="#000" stroke-width=".8"/>')
        if n <= 7:
            p.append(f'<text x="{x+bw/2:.1f}" y="{y-3:.1f}" font-size="7.5" font-weight="bold" text-anchor="middle">{r["HI"]}</text>')
        if i % step == 0 or i == n - 1 and n <= 12:
            p.append(f'<text x="{x+bw/2:.1f}" y="{H-21}" font-size="6.5" text-anchor="middle">{r["Label"]}</text>')
            if r["Sub"]:
                p.append(f'<text x="{x+bw/2:.1f}" y="{H-13}" font-size="6" text-anchor="middle" fill="#555">{r["Sub"]}</text>')
    p.append(f'<line x1="{L}" y1="{Y(lo):.1f}" x2="{W-R}" y2="{Y(lo):.1f}" stroke="#000" stroke-width=".8"/>')
    p.append(f'<text x="{L}" y="{H-2}" font-size="6" fill="#555">{note}</text>')
    p.append("</svg>")
    return "".join(p)


def _svg_trend(hist_years, hist_vals, years, vals, lo_b, hi_b, fourh):
    W, H, L, R, T, B = 360, 170, 30, 12, 14, 36
    pw, ph = W - L - R, H - T - B
    hy = [float(v) for v in hist_years]
    hv = [float(v) for v in hist_vals]
    vals = [float(v) for v in vals]
    allv = hv + vals + ([float(v) for v in lo_b] if lo_b is not None else []) + ([float(v) for v in hi_b] if hi_b is not None else [])
    lo, hi = min(allv) - 1.5, max(allv) + 1.5
    x0, x1 = min(hy + list(years)), max(hy + list(years))
    X = lambda yr: L + pw * (yr - x0) / (x1 - x0 if x1 > x0 else 1)
    Y = lambda v: T + ph * (1 - (v - lo) / (hi - lo))
    p = [f'<svg viewBox="0 0 {W} {H}" width="100%" xmlns="http://www.w3.org/2000/svg" font-family="Courier New,monospace">']
    for z in fourh:
        b0, b1 = max(z["lo"], lo), min(z["hi"], hi)
        if b1 > b0:
            p.append(f'<rect x="{L}" y="{Y(b1):.1f}" width="{pw}" height="{Y(b0)-Y(b1):.1f}" fill="{z["color"]}" fill-opacity=".25"/>'
                     f'<text x="{W-R-2}" y="{Y(b1)+8:.1f}" font-size="6.5" text-anchor="end" fill="#000">{z["label"].upper()}</text>')
    for v in range(int(np.ceil(lo)), int(hi) + 1):
        if v % 2 == 0:
            p.append(f'<text x="{L-4}" y="{Y(v)+2.5:.1f}" font-size="7" text-anchor="end" fill="#555">{v}</text>')
    if lo_b is not None and hi_b is not None:
        up = " ".join(f"{X(y):.1f},{Y(v):.1f}" for y, v in zip(years, hi_b))
        dn = " ".join(f"{X(y):.1f},{Y(v):.1f}" for y, v in reversed(list(zip(years, lo_b))))
        p.append(f'<polygon points="{up} {dn}" fill="#000" fill-opacity=".12"/>')
    if len(hy) > 1:
        p.append(f'<polyline points="{" ".join(f"{X(y):.1f},{Y(v):.1f}" for y, v in zip(hy, hv))}" fill="none" stroke="#666" stroke-width=".8"/>')
    for y, v in zip(hy, hv):
        p.append(f'<circle cx="{X(y):.1f}" cy="{Y(v):.1f}" r="2" fill="#fff" stroke="#000" stroke-width=".8"/>')
    p.append(f'<polyline points="{" ".join(f"{X(y):.1f},{Y(v):.1f}" for y, v in zip(years, vals))}" fill="none" stroke="#000" stroke-width="1.5"/>')
    if len(years) <= 20:
        for y, v in zip(years, vals):
            p.append(f'<circle cx="{X(y):.1f}" cy="{Y(v):.1f}" r="2" fill="#000"/>')
    p.append(f'<text x="{X(years[-1]):.1f}" y="{Y(vals[-1])-5:.1f}" font-size="7.5" font-weight="bold" text-anchor="end">{vals[-1]:.1f}</text>')
    step = max(1, int(np.ceil((x1 - x0) / 7)))
    for y in range(int(x0), int(x1) + 1):
        if (y - int(x0)) % step == 0:
            p.append(f'<text x="{X(y):.1f}" y="{H-22}" font-size="6.5" text-anchor="middle">{y}</text>')
    p.append(f'<line x1="{L}" y1="{T+ph}" x2="{W-R}" y2="{T+ph}" stroke="#000" stroke-width=".8"/>')
    p.append(f'<text x="{L}" y="{H-3}" font-size="6" fill="#555">o observed annual peak &#183; solid line = projection'
             f'{" &#183; shaded = 95% range" if lo_b is not None else ""}</text>')
    p.append("</svg>")
    return "".join(p)


def _svg_barcode(code):
    seed = f"{zlib.crc32(code.encode()):08x}{zlib.crc32(code[::-1].encode()):08x}"
    x, parts, dark = 0, [], True
    for ch in seed * 2:
        w = int(ch, 16) % 3 + 1
        if dark:
            parts.append(f'<rect x="{x}" y="0" width="{w}" height="34" fill="#000"/>')
        x += w
        dark = not dark
    return (f'<svg viewBox="0 0 {x} 34" width="70%" height="38" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">'
            + "".join(parts) + "</svg>")


