# ------------------------------------------------------------------ receipt register (traceability)
REG_COLS = ["Serial", "Reference", "Type", "Location", "Latitude", "Longitude", "Station", "Window",
            "Issued_PHT", "Issued_By", "Peak_HI_C", "Highest_Level", "Auth_Code", "SHA256_html", "Files"]
TYPE_CODE = {"3 days": "3DAY", "1 week": "1WEEK", "1 month": "1MONTH", "3 years": "3YEAR",
             "10 years": "10YEAR", "20 years": "20YEAR", "30 years": "30YEAR", "Custom dates": "CUSTOM"}


def _receipts_dir():
    try:
        try:
            base = pathlib.Path(__file__).resolve().parent
        except NameError:
            base = pathlib.Path.cwd()
        d = base / "receipts"
        d.mkdir(exist_ok=True)
        return d
    except Exception:
        return None


def _read_register(d):
    if d is not None and (d / "register.csv").exists():
        try:
            return pd.read_csv(d / "register.csv", dtype=str).fillna("")
        except Exception:
            pass
    return pd.DataFrame(columns=REG_COLS)


def _slug(text, n=40):
    t = re.sub(r"[^A-Za-z0-9]+", "-", str(text)).strip("-")
    return (t[:n].strip("-")) or "Location"


def _issue_receipt(*, d, df, horizon, place, lat, lon, station, window, issued_by, html_builder):
    """Assign serial + reference, save html/csv, append to register. Returns dict."""
    now = datetime.now(timezone(timedelta(hours=8)))
    reg = _read_register(d)
    try:
        serial_n = int(pd.to_numeric(reg["Serial"], errors="coerce").max()) + 1 if len(reg) else 1
    except Exception:
        serial_n = len(reg) + 1
    serial = f"{serial_n:04d}"
    ref = f"MOROPORO_{TYPE_CODE[horizon]}_{_slug(place)}_{now.strftime('%Y%m%d')}_{serial}"
    while d is not None and (d / f"{ref}.html").exists():
        serial_n += 1
        serial = f"{serial_n:04d}"
        ref = f"MOROPORO_{TYPE_CODE[horizon]}_{_slug(place)}_{now.strftime('%Y%m%d')}_{serial}"
    html = html_builder(ref=ref, serial=serial, issued_at=now)
    out = {"ref": ref, "serial": serial, "html": html, "saved": False, "error": None, "dir": d}
    if d is None:
        out["error"] = "no writable folder"
        return out
    try:
        (d / f"{ref}.html").write_text(html, encoding="utf-8")
        df.drop(columns=["Color"], errors="ignore").to_csv(d / f"{ref}.csv", index=False)
        peak = df.loc[df["HI"].idxmax()]
        row = {"Serial": serial, "Reference": ref, "Type": horizon, "Location": place, "Latitude": f"{lat:.5f}",
               "Longitude": f"{lon:.5f}", "Station": station, "Window": window,
               "Issued_PHT": now.strftime("%Y-%m-%d %H:%M:%S"), "Issued_By": issued_by or "",
               "Peak_HI_C": f"{peak['HI']:.1f}", "Highest_Level": peak["Level"],
               "Auth_Code": auth_code(ref, now.strftime("%Y-%m-%d %H:%M:%S"), f"{lat:.5f}", f"{lon:.5f}", f"{peak['HI']:.1f}"),
               "SHA256_html": hashlib.sha256(html.encode("utf-8")).hexdigest(),
               "Files": f"{ref}.html; {ref}.csv; {ref}.pdf (downloaded from browser)"}
        pd.concat([reg, pd.DataFrame([row])], ignore_index=True)[REG_COLS].to_csv(d / "register.csv", index=False)
        out["saved"] = True
    except Exception as ex:
        out["error"] = str(ex)
    return out


# ------------------------------------------------------------------ A4 situation report (location + heat map)
_RAMP = [(24, (38, 99, 235)), (27, (34, 197, 160)), (30, (140, 220, 80)), (33, (250, 210, 60)),
         (37.5, (250, 140, 40)), (42, (235, 50, 40)), (46, (140, 10, 40))]


def _ramp_rgb(v):
    if v <= _RAMP[0][0]:
        return _RAMP[0][1]
    for (a, ca), (b, cb) in zip(_RAMP, _RAMP[1:]):
        if v <= b:
            f = (v - a) / (b - a)
            return tuple(ca[i] + (cb[i] - ca[i]) * f for i in range(3))
    return _RAMP[-1][1]


def _haversine_km(a_lat, a_lon, b_lat, b_lon):
    p = math.pi / 180
    h = math.sin((b_lat - a_lat) * p / 2) ** 2 + math.cos(a_lat * p) * math.cos(b_lat * p) * math.sin((b_lon - a_lon) * p / 2) ** 2
    return 12742 * math.asin(math.sqrt(h))


def _a4_heatmap(lat, lon, pts, target_hi, place, z=8, W=706, H=400, cell=10, level_color="#FF4D5E"):
    """Map picture for the report: OSM tiles + IDW heat overlay + stations + target pin + scale bar.
    pts = [(name, lat, lon, value), ...]. If tiles cannot load, the heat overlay still renders on a grey base."""
    e = _html.escape
    n = 256 * 2 ** z

    def merc(la, lo):
        s = math.sin(math.radians(la))
        return (lo + 180) / 360 * n, (0.5 - math.log((1 + s) / (1 - s)) / (4 * math.pi)) * n

    cx, cy = merc(lat, lon)
    x0, y0 = cx - W / 2, cy - H / 2
    imgs = []
    for tx in range(int(x0 // 256), int((x0 + W) // 256) + 1):
        for ty in range(int(y0 // 256), int((y0 + H) // 256) + 1):
            if 0 <= ty < 2 ** z:
                imgs.append(f'<img crossorigin="anonymous" src="https://tile.openstreetmap.org/{z}/{tx % (2 ** z)}/{ty}.png" '
                            f'style="position:absolute;left:{tx * 256 - x0:.1f}px;top:{ty * 256 - y0:.1f}px;width:256px;height:256px;"/>')
    gx = np.arange(0, W, cell) + cell / 2 + x0
    gy = np.arange(0, H, cell) + cell / 2 + y0
    GX, GY = np.meshgrid(gx, gy)
    glon = GX / n * 360 - 180
    glat = np.degrees(np.arctan(np.sinh(np.pi * (1 - 2 * GY / n))))
    slat = np.array([p[1] for p in pts]); slon = np.array([p[2] for p in pts]); sv = np.array([p[3] for p in pts])
    k = np.cos(np.radians(glat))[..., None]
    d2 = ((glon[..., None] - slon) * k) ** 2 + (glat[..., None] - slat) ** 2
    wgt = 1.0 / (d2 + 0.35)
    val = (wgt * sv).sum(-1) / wgt.sum(-1)
    alpha = np.clip(1 - (np.sqrt(d2.min(-1)) - 1.4) / 2.2, 0, 1)
    rects = []
    for iy in range(val.shape[0]):
        for ix in range(val.shape[1]):
            if alpha[iy, ix] < 0.03:
                continue
            c = _ramp_rgb(float(val[iy, ix]))
            rects.append(f'<rect x="{ix * cell}" y="{iy * cell}" width="{cell + 0.6}" height="{cell + 0.6}" '
                         f'fill="rgb({int(c[0])},{int(c[1])},{int(c[2])})" fill-opacity="{0.60 * alpha[iy, ix]:.2f}"/>')
    marks = []
    for name, la, lo, v in pts:
        px, py = merc(la, lo)
        px -= x0; py -= y0
        if -5 <= px <= W + 5 and -5 <= py <= H + 5:
            marks.append(f'<circle cx="{px:.1f}" cy="{py:.1f}" r="4" fill="#111" stroke="#fff" stroke-width="1.5"/>'
                         f'<text x="{px + 7:.1f}" y="{py + 3:.1f}" font-size="10" font-family="Arial" font-weight="bold" fill="#111" '
                         f'stroke="#fff" stroke-width="3" paint-order="stroke">{e(name)} {v:.1f}&#176;</text>')
    label = e(place if len(place) <= 46 else place[:44] + "…")
    marks.append(f'<circle cx="{W / 2}" cy="{H / 2}" r="10" fill="{level_color}" stroke="#fff" stroke-width="3"/>'
                 f'<circle cx="{W / 2}" cy="{H / 2}" r="3" fill="#fff"/>'
                 f'<text x="{W / 2}" y="{H / 2 - 17}" font-size="11.5" font-family="Arial" font-weight="bold" text-anchor="middle" '
                 f'fill="#000" stroke="#fff" stroke-width="4" paint-order="stroke">{label} &#183; {target_hi:.1f}&#176;C</text>')
    mpp = 156543.03 * math.cos(math.radians(lat)) / 2 ** z
    km = 50 if W * mpp / 1000 > 120 else 20 if W * mpp / 1000 > 50 else 10
    bar = km * 1000 / mpp
    marks.append(f'<rect x="{W - bar - 20:.0f}" y="{H - 26}" width="{bar:.0f}" height="5" fill="#000" stroke="#fff" stroke-width="1.5"/>'
                 f'<text x="{W - bar - 20:.0f}" y="{H - 31}" font-size="10" font-family="Arial" font-weight="bold" fill="#000" '
                 f'stroke="#fff" stroke-width="3" paint-order="stroke">{km} km</text>')
    stops = ",".join(f"rgb({int(c[0])},{int(c[1])},{int(c[2])}) {(v - 24) / 22 * 100:.1f}%" for v, c in _RAMP)
    ticks = "".join(f'<i style="left:{(v - 24) / 22 * 100:.1f}%">{v}</i>' for v in (24, 27, 33, 42, 46))
    cuts = "".join(f'<u style="left:{(v - 24) / 22 * 100:.1f}%"></u>' for v in (27, 33, 42))
    return (f'<div style="position:relative;width:{W}px;height:{H}px;overflow:hidden;background:#dfe5ea;border:1px solid #000;">'
            + "".join(imgs)
            + f'<svg width="{W}" height="{H}" viewBox="0 0 {W} {H}" xmlns="http://www.w3.org/2000/svg" style="position:absolute;left:0;top:0">'
            + "".join(rects) + "".join(marks) + '</svg>'
            f'<div style="position:absolute;left:4px;bottom:2px;font:8px Arial;color:#222;background:rgba(255,255,255,.7);padding:0 3px">&copy; OpenStreetMap contributors</div></div>'
            f'<div class="lg"><div class="lgbar" style="background:linear-gradient(90deg,{stops})">{cuts}{ticks}</div></div>')


